import {
	existsSync, readdirSync, readFileSync, rmSync, writeFileSync,
} from "node:fs";
import { join, relative } from "node:path";
import type { Plugin } from "vite";
import {
	CompileContracts, FormatDiagnostic,
} from "../../Modules/Scripting/Source/Contracts/Index.ts";

/** What generated files start with (only those are ever removed). */
const GeneratedMarks = [
	"// Generated from a .contract file by the engine",
	"// <auto-generated>",
];

const Skipped = new Set( ["node_modules", "Binaries", "obj", "bin", ".cse"] );

/** Files under a folder, with forward-slash paths relative to `root`. */
function Walk( folder: string, root: string, out: string[] = [] ): string[] {
	for ( const entry of readdirSync( folder, { withFileTypes: true } ) ) {
		const path = join( folder, entry.name );

		if ( entry.isDirectory() ) {
			if ( !Skipped.has( entry.name ) ) {
				Walk( path, root, out );
			}
		}
		else {
			out.push( relative( root, path ).replaceAll( "\\", "/" ) );
		}
	}
	return out;
}

export interface ContractsResult {
	/** Generated files written (changed ones only), relative to the project. */
	Written: string[];
	/** Generated files of .contract files that are gone. */
	Removed: string[];
	/**
	 * "path:line:column: message" for each problem (then nothing is written).
	 */
	Errors: string[];
}

/**
 * Compiles a project's .contract files (anywhere under Source/) into the
 * TypeScript next to each, and the C# when the project has C# scripts.
 */
export function GenerateContracts(
	directory: string,
	csharp: boolean,
): ContractsResult {
	const source = join( directory, "Source" );
	const files = existsSync( source ) ? Walk( source, directory ) : [];
	const contracts = files.filter( ( path ) => path.endsWith( ".contract" ) );
	const result = CompileContracts(
		contracts.map( ( path ) => ( {
			Path: path,
			Text: readFileSync( join( directory, path ), "utf8" ),
		} ) ),
		{ CSharp: csharp },
	);
	const outcome: ContractsResult = {
		Written: [], Removed: [],
		Errors: result.Diagnostics.map( FormatDiagnostic ),
	};

	for ( const output of result.Outputs ) {
		const path = join( directory, output.Path );

		if ( !existsSync( path )
			|| readFileSync( path, "utf8" ) !== output.Text ) {
			writeFileSync( path, output.Text );
			outcome.Written.push( output.Path );
		}
	}
	for ( const path of files ) {
		const generated = /\.contract\.(ts|cs)$/.exec( path );

		if ( !generated || contracts.includes( path.slice( 0, -3 ) ) ) {
			continue;
		}
		const text = readFileSync( join( directory, path ), "utf8" );

		if ( GeneratedMarks.some( ( mark ) => text.startsWith( mark ) ) ) {
			rmSync( join( directory, path ) );
			outcome.Removed.push( path );
		}
	}
	return outcome;
}

export interface ContractsPluginOptions {
	/** The project's folder. */
	Directory: string;
	/** Whether it has C# scripts (a .csproj): the C# side is written too. */
	CSharp: boolean;
}

/**
 * Keeps a project's .contract files compiled: when the build starts, and in
 * development whenever one changes. A problem fails the build; in
 * development it shows in the browser's overlay.
 */
export function ContractsPlugin( options: ContractsPluginOptions ): Plugin {
	const run = (): ContractsResult => GenerateContracts(
		options.Directory,
		options.CSharp,
	);
	const Message = ( errors: string[] ): string => (
		"contracts: the .contract files have problems:\n"
			+ errors.join( "\n" )
	);

	let serving = false;

	return {
		name: "cse-contracts",

		configResolved( config ) {
			serving = config.command === "serve";
		},

		buildStart() {
			const { Errors } = run();

			if ( Errors.length > 0 ) {
				// the dev server keeps running (the overlay shows it on change)
				if ( serving ) {
					this.warn( Message( Errors ) );
				}
				else {
					this.error( Message( Errors ) );
				}
			}
		},

		configureServer( server ) {
			server.watcher.add(
				join( options.Directory, "Source/**/*.contract" ),
			);
			const changed = ( file: string ): void => {
				if ( !file.endsWith( ".contract" ) ) {
					return;
				}
				const { Errors, Written } = run();

				if ( Errors.length > 0 ) {
					server.config.logger.error( Message( Errors ) );
					server.ws.send( {
						type: "error",
						err: { message: Message( Errors ), stack: "" },
					} );
				}
				else if ( Written.length > 0 ) {
					server.config.logger.info(
						`contracts: wrote ${ Written.join( ", " ) }`,
					);
				}
			};
			server.watcher.on( "add", changed );
			server.watcher.on( "change", changed );
			server.watcher.on( "unlink", changed );
		},
	};
}
